<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { acknowledgeBusinessAction, listenForBusinessActions, pendingBusinessActions } from '../businessActionSync.js'

const props = defineProps({ page: String, permissions: { type: Array, default: () => [] }, roles: { type: Array, default: () => [] }, baseCurrency: { type: String, default: 'PHP' }, userId: { type: [Number, String], default: '' } })
const can = (name) => props.permissions.includes(name)
const pageTitles = {
  'sales-cost-estimates': ['Cost Estimates', 'Forecast shipment costs and funding before preparing a client offer.'],
  'accounting-cost-review': ['Cost Forecast Review', 'Review submitted expense lines and funding assumptions.'],
  'finance-cost-review': ['Cost Review', 'Review cost exposure linked to commercial offers.'],
  'accounting-cash-requirements': ['Cash Requirement Forecast', 'Planned funding needs, separate from payments.'],
  'sales-quotations': ['Quotations', 'Prepare client offers from reviewed cost estimates.'],
  'sales-quotation-history': ['Quotation History', 'Review versions, client decisions and accepted baselines.'],
  'finance-margins': ['Margin Analysis', 'Review projected offer margins and cost exposure.'],
  'finance-approval-queue': ['Quotation Approval Queue', 'Review commercial offers before they are issued.'],
}
const [title, subtitle] = pageTitles[props.page] || pageTitles['sales-quotations']
const busy = ref(false), saving = ref(false), error = ref(''), notice = ref(''), expired = ref(false)
const estimates = ref([]), quotes = ref([]), inquiries = ref([]), forecasts = ref([]), cashRows = ref([]), marginRows = ref([]), dashboard = ref({})
const search = ref(''), status = ref(props.page === 'finance-approval-queue' ? 'submitted' : ''), pageNumber = ref(1), lastPage = ref(1), rowCount = ref(0)
const dialog = ref(''), selected = ref(null), detail = ref(null), comparison = ref(null), preview = ref(null), targetMargin = ref('')
const kind = computed(() => props.page.includes('cost-estimates') || props.page.includes('cost-review') ? 'estimate' : props.page.includes('cash-requirements') ? 'cash' : props.page === 'finance-margins' ? 'margin' : props.page.includes('quotations') || props.page.includes('approval-queue') ? 'quote' : 'other')
const approvedEstimates = computed(() => estimates.value.filter((e) => e.available_for_quotation))
const matchingForecasts = computed(() => forecasts.value.filter((f) => String(f.inquiry_id) === String(estimateForm.value.inquiry_id)))
const makeEstimateLine = () => ({ category: 'shipping_line', description: '', supplier: '', quantity: '1', unit: 'shipment', unit_cost: '', currency: props.baseCurrency, exchange_rate_to_estimate: '', exchange_rate_source: '', exchange_rate_date: '', tax_treatment: 'none', tax_rate: '0', cost_type: 'direct', cost_payer: 'company', recoverability: 'nonrecoverable', funding_required: false, notes: '' })
const makeQuoteLine = () => ({ description: '', quantity: '1', unit: 'shipment', unit_price: '', discount_type: 'none', discount_value: '0', tax_treatment: 'none', tax_rate: '0' })
const estimateForm = ref({ inquiry_id: '', forecast_id: '', currency: props.baseCurrency, assumptions: '', lock_version: 1, lines: [makeEstimateLine()] })
const quoteForm = ref({ cost_estimate_id: '', client_contact: '', service_scope: '', origin: '', destination: '', cargo_description: '', planned_window: '', valid_until: '', terms: '', payment_terms: '', exclusions: '', assumptions: '', internal_notes: '', customer_remarks: '', lines: [makeQuoteLine()] })
const reviewForm = ref({ stage: props.roles.includes('Finance') ? 'finance' : 'accounting', decision: 'approved', remarks: '' })
const responseForm = ref({ response: 'accepted', client_representative: '', quotation_version: 1, responded_at: new Date().toISOString().slice(0, 16), evidence_reference: '', remarks: '' })
const revisionForm = ref({ cost_estimate_id: '', reason: '' })

async function request(url, options = {}) {
  const response = await fetch(url, { credentials: 'same-origin', ...options, headers: { Accept: 'application/json', ...(options.body ? { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '' } : {}), ...(options.headers || {}) } })
  const data = await response.json().catch(() => ({}))
  if (!response.ok) {
    expired.value = response.status === 401 || response.status === 419
    error.value = response.status === 401 ? 'Your IFC sign-in session has expired.' : response.status === 419 ? 'Your session or security token expired.' : response.status === 403 ? 'Your account does not have permission to perform this action.' : response.status === 422 ? Object.values(data.errors || {}).flat().join(' ') || data.message || 'Check the entered details.' : data.message || `Request failed (${response.status}).`
    throw new Error(error.value)
  }
  expired.value = false
  return data
}
function query() { const q = new URLSearchParams({ page: String(pageNumber.value) }); if (search.value) q.set('search', search.value); if (status.value) q.set('status', status.value); return q.toString() }
async function load() {
  busy.value = true; error.value = ''
  try {
    const tasks = []
    if (kind.value === 'estimate' || can('quotations.create')) tasks.push(request(`/api/commercial/cost-estimates?${query()}`).then((r) => { estimates.value = r.data || []; rowCount.value = r.total ?? estimates.value.length; lastPage.value = r.last_page ?? 1 }))
    if (kind.value === 'quote') tasks.push(request(`/api/commercial/quotations?${query()}`).then((r) => { quotes.value = r.data || []; rowCount.value = r.total ?? quotes.value.length; lastPage.value = r.last_page ?? 1 }))
    if (kind.value === 'cash') tasks.push(request('/api/commercial/cash-requirements').then((r) => { cashRows.value = r || [] }))
    if (kind.value === 'margin') tasks.push(request('/api/commercial/margins').then((r) => { marginRows.value = r.data || []; rowCount.value = r.total || 0; lastPage.value = r.last_page || 1 }))
    if (kind.value === 'estimate' && can('cost-estimates.create')) { tasks.push(request('/api/sales/inquiries?per_page=100').then((r) => { inquiries.value = r.data || [] })); tasks.push(request('/api/sales/forecasts?per_page=100').then((r) => { forecasts.value = r.data || [] })) }
    if (kind.value === 'estimate' || kind.value === 'quote') tasks.push(request('/api/commercial/dashboard').then((r) => { dashboard.value = r.data || {} }))
    await Promise.all(tasks)
  } catch { /* show the request error rather than a misleading empty list */ } finally { busy.value = false }
}
function newEstimate() { selected.value = null; estimateForm.value = { inquiry_id: '', forecast_id: '', currency: props.baseCurrency, assumptions: '', lock_version: 1, lines: [makeEstimateLine()] }; dialog.value = 'estimate'; error.value = '' }
function newQuote() { selected.value = null; quoteForm.value = { cost_estimate_id: '', client_contact: '', service_scope: '', origin: '', destination: '', cargo_description: '', planned_window: '', valid_until: '', terms: '', payment_terms: '', exclusions: '', assumptions: '', internal_notes: '', customer_remarks: '', lines: [makeQuoteLine()] }; dialog.value = 'quote'; error.value = '' }
function addLine(lines, create) { lines.push(create()) }
function removeLine(lines, index) { if (lines.length > 1) lines.splice(index, 1) }
function isPastDate(value) { return Boolean(value && value < new Date().toISOString().slice(0, 10)) }
function chooseEstimate() { const e = estimates.value.find((item) => String(item.id) === String(quoteForm.value.cost_estimate_id)); if (!e) return; quoteForm.value.origin = e.origin; quoteForm.value.destination = e.destination; quoteForm.value.service_scope = `${e.shipment_classification} ${e.transport_mode} freight service`; quoteForm.value.planned_window = e.planned_window?.slice(0, 10) || ''; quoteForm.value.client_contact = e.inquiry?.client?.contact_name || ''; quoteForm.value.lines[0].description ||= quoteForm.value.service_scope }
async function openEstimate(row, edit = false) { try { detail.value = (await request(`/api/commercial/cost-estimates/${row.id}`)).data; selected.value = detail.value; if (edit) { estimateForm.value = { ...detail.value, lines: detail.value.lines }; dialog.value = 'estimate' } else dialog.value = 'estimate-view' } catch { /* alert visible */ } }
async function openQuote(row, edit = false) { try { detail.value = (await request(`/api/commercial/quotations/${row.id}`)).data; selected.value = detail.value; if (edit) { quoteForm.value = { ...detail.value, lines: detail.value.lines }; dialog.value = 'quote' } else dialog.value = 'quote-view' } catch { /* alert visible */ } }
async function saveEstimate() { saving.value = true; try { const body = { ...estimateForm.value, currency: estimateForm.value.currency.toUpperCase(), lines: estimateForm.value.lines.map((l) => ({ ...l, currency: l.currency.toUpperCase() })) }; const edit = Boolean(selected.value?.id); const result = await request(edit ? `/api/commercial/cost-estimates/${selected.value.id}` : '/api/commercial/cost-estimates', { method: edit ? 'PUT' : 'POST', body: JSON.stringify(body) }); notice.value = `${result.data.reference} saved as a draft.`; dialog.value = ''; await load() } catch { /* validation feedback visible */ } finally { saving.value = false } }
async function saveQuote() { saving.value = true; try { const edit = Boolean(selected.value?.id); const result = await request(edit ? `/api/commercial/quotations/${selected.value.id}` : '/api/commercial/quotations', { method: edit ? 'PUT' : 'POST', body: JSON.stringify(quoteForm.value) }); notice.value = `${result.data.reference} saved as a draft.`; dialog.value = ''; await load() } catch { /* validation feedback visible */ } finally { saving.value = false } }
async function post(path, body = {}, message = 'Action completed.') { saving.value = true; try { const r = await request(path, { method: 'POST', body: JSON.stringify(body) }); notice.value = r.message || message; dialog.value = ''; await load() } catch { /* validation feedback visible */ } finally { saving.value = false } }
function submitEstimate(row) { selected.value = row; post(`/api/commercial/cost-estimates/${row.id}/submit`, {}, 'Estimate submitted for review.') }
function reviewEstimate(row) { selected.value = row; reviewForm.value = { stage: 'accounting', decision: 'approved', remarks: '' }; dialog.value = 'estimate-review' }
function submitQuote(row) { selected.value = row; post(`/api/commercial/quotations/${row.id}/submit`, {}, 'Quotation submitted for internal review.') }
function reviewQuote(row) { selected.value = row; reviewForm.value = { stage: props.roles.includes('Finance') ? 'finance' : 'accounting', decision: 'approved', remarks: '' }; dialog.value = 'quote-review' }
function clientResponse(row) { selected.value = row; responseForm.value = { response: 'accepted', client_representative: row.client_contact || '', quotation_version: row.version, responded_at: new Date().toISOString().slice(0,16), evidence_reference: '', remarks: '' }; dialog.value = 'client-response' }
function newVersion(row) { selected.value = row; revisionForm.value = { cost_estimate_id: '', reason: '' }; dialog.value = 'quote-revision' }
async function saveReview() { const isEstimate = dialog.value === 'estimate-review'; const path = isEstimate ? `/api/commercial/cost-estimates/${selected.value.id}/review` : `/api/commercial/quotations/${selected.value.id}/review`; await post(path, isEstimate ? { decision: reviewForm.value.decision, remarks: reviewForm.value.remarks } : reviewForm.value, 'Review recorded.') }
async function marginPreview() { const e = estimates.value.find((item) => String(item.id) === String(quoteForm.value.cost_estimate_id)); if (!e) { error.value = 'Choose an approved estimate first.'; return } try { preview.value = (await request('/api/commercial/margin-preview', { method: 'POST', body: JSON.stringify({ cost_estimate_id: e.id, lines: quoteForm.value.lines, target_margin_percent: targetMargin.value || undefined }) })).data } catch { /* alert visible */ } }
async function compare(row) { try { comparison.value = (await request(`/api/commercial/quotations/${row.id}/compare`)).data } catch { /* alert visible */ } }
const money = (value, currency) => `${currency || props.baseCurrency} ${value ?? '0.00'}`
const salesSummary = computed(() => dashboard.value.sales || {})
const accountingSummary = computed(() => dashboard.value.accounting || {})
const financeSummary = computed(() => dashboard.value.finance || {})
const stopActionSync = listenForBusinessActions(props.userId, 'inquiry-selectors', load)
onBeforeUnmount(stopActionSync)
onMounted(async () => {
  const pendingSyncs = pendingBusinessActions(props.userId, 'inquiry-selectors')
  await load()
  pendingSyncs.forEach(event => acknowledgeBusinessAction(event.id, props.userId, 'inquiry-selectors'))
  const requestedInquiryId = new URLSearchParams(window.location.search).get('inquiry_id')
  const inquiryId = /^\d+$/.test(requestedInquiryId || '') && Number(requestedInquiryId) > 0 ? requestedInquiryId : null
  let inquiry = inquiries.value.find(item => String(item.id) === String(inquiryId))
  if (!inquiry && inquiryId && props.page === 'sales-cost-estimates' && can('inquiries.view')) {
    try {
      inquiry = (await request(`/api/sales/inquiries/${encodeURIComponent(inquiryId)}`)).data
      if (inquiry) inquiries.value = [inquiry, ...inquiries.value]
    } catch { /* display the authorized lookup error */ }
  }
  if (props.page === 'sales-cost-estimates' && inquiry && can('cost-estimates.create') && ['under_review', 'forecasted'].includes(inquiry.status)) {
    newEstimate()
    estimateForm.value.inquiry_id = String(inquiry.id)
  }
})
</script>

<template>
  <section class="commercial-workspace">
    <header class="commercial-heading"><div><div class="ifc-kicker">INTERFREIGHT GROUP / PHASE 3</div><h1>{{ title }}</h1><p>{{ subtitle }}</p></div><div><button v-if="page === 'sales-cost-estimates' && can('cost-estimates.create')" class="ifc-primary" @click="newEstimate">+ New cost estimate</button><button v-if="page === 'sales-quotations' && can('quotations.create')" class="ifc-primary" :disabled="!approvedEstimates.length" @click="newQuote">+ New quotation</button></div></header>
    <div v-if="error" class="commercial-alert" role="alert"><span>{{ error }}</span><a v-if="expired" href="/login">Sign in again</a><button v-else @click="load">Retry</button></div><div v-if="notice" class="commercial-notice" role="status">{{ notice }}<button aria-label="Dismiss" @click="notice = ''">&times;></button></div>

    <section v-if="page === 'sales-quotations' && dashboard.sales && !expired" class="commercial-kpis"><article><span>DRAFTS</span><b>{{ salesSummary.draft || 0 }}</b></article><article><span>PENDING APPROVAL</span><b>{{ salesSummary.pending_approval || 0 }}</b></article><article><span>ISSUED  AWAITING CLIENT</span><b>{{ salesSummary.awaiting_client || 0 }}</b></article><article><span>CLIENT ACCEPTED</span><b>{{ salesSummary.accepted || 0 }}</b></article><article v-for="item in salesSummary.projected_offer_value || []" :key="item.currency"><span>PROJECTED OFFER VALUE  {{ item.currency }}</span><b>{{ money(item.total,item.currency) }}</b><small>Unaccepted offers are not confirmed revenue.</small></article></section>
    <section v-if="page.startsWith('accounting-') && dashboard.accounting && !expired" class="commercial-kpis"><article><span>ESTIMATES WAITING FOR REVIEW</span><b>{{ accountingSummary.waiting_for_review || 0 }}</b></article><article><span>FORECASTS WITHOUT APPROVED COSTS</span><b>{{ accountingSummary.unestimated_forecasts || 0 }}</b></article><article v-for="item in accountingSummary.cost_demand || []" :key="item.period + item.currency"><span>{{ item.period }} COST FORECAST</span><b>{{ money(item.estimated_cost,item.currency) }}</b></article></section>
    <section v-if="page.startsWith('finance-') && dashboard.finance && !expired" class="commercial-kpis"><article><span>QUOTATIONS AWAITING DECISION</span><b>{{ financeSummary.approval_queue || 0 }}</b></article><article v-for="item in financeSummary.estimated_cost_exposure || []" :key="item.currency"><span>ESTIMATED COST EXPOSURE  {{ item.currency }}</span><b>{{ money(item.total,item.currency) }}</b></article></section>

    <section v-if="kind === 'cash' && !expired" class="ifc-panel commercial-panel"><header class="ifc-panel-head"><div><h2>Funding requirements by planned month</h2><p>Funding flags are separate from estimated expenses, payments and accounting entries.</p></div></header><div class="ifc-table-wrap"><table><thead><tr><th>MONTH</th><th>CURRENCY</th><th>FUNDING REQUIRED</th><th>ESTIMATES</th></tr></thead><tbody><tr v-for="item in cashRows" :key="item.period + item.currency"><td>{{ item.period || 'Not scheduled' }}</td><td>{{ item.currency }}</td><td>{{ money(item.funding_required,item.currency) }}</td><td>{{ item.estimate_count }}</td></tr><tr v-if="!busy && !cashRows.length && !error"><td colspan="4" class="ifc-empty">No submitted or approved funding requirements are recorded.</td></tr></tbody></table></div></section>
    <section v-if="kind === 'margin' && !expired" class="ifc-panel commercial-panel"><header class="ifc-panel-head"><div><h2>Projected offer profitability</h2><p>Offer values remain projections until client acceptance.</p></div></header><div class="ifc-table-wrap"><table><thead><tr><th>QUOTATION</th><th>STATUS</th><th>OFFER VALUE</th><th>ESTIMATED COST</th><th>GROSS PROFIT</th><th>MARGIN</th></tr></thead><tbody><tr v-for="item in marginRows" :key="item.id"><td><b>{{ item.reference }} v{{ item.version }}</b><small>{{ item.client }}</small></td><td>{{ item.status.replaceAll('_',' ') }}</td><td>{{ money(item.total,item.currency) }}</td><td>{{ money(item.margin.total_estimated_cost,item.currency) }}</td><td :class="{ 'commercial-loss': item.margin.warning === 'loss' }">{{ money(item.margin.gross_profit,item.currency) }}</td><td>{{ item.margin.gross_margin_percent ?? 'N/A' }}%<small v-if="item.margin.warning">{{ item.margin.warning.replaceAll('_',' ') }}</small></td></tr><tr v-if="!busy && !marginRows.length && !error"><td colspan="6" class="ifc-empty">No reviewed offers are available.</td></tr></tbody></table></div></section>

    <section v-if="(kind === 'estimate' || kind === 'quote') && page !== 'finance-margins' && !expired" class="ifc-panel commercial-panel"><div class="commercial-toolbar"><input v-model="search" placeholder="Search reference or client" aria-label="Search commercial records" @keyup.enter="pageNumber = 1; load()"><select v-model="status" aria-label="Filter status" @change="pageNumber = 1; load()"><option value="">All statuses</option><option v-for="item in ['draft','submitted','revision_requested','approved','rejected','issued','client_accepted','client_rejected','expired','superseded']" :key="item" :value="item">{{ item.replaceAll('_',' ') }}</option></select><span>{{ busy ? 'Loading' : error ? 'Record count unavailable' : `${rowCount} records` }}</span></div>
      <div class="ifc-table-wrap"><table v-if="kind === 'estimate'"><thead><tr><th>ESTIMATE</th><th>INQUIRY / CLIENT</th><th>VERSION</th><th>ESTIMATED COST</th><th>FUNDING</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="item in estimates" :key="item.id"><td><b>{{ item.reference }}</b><small>{{ item.created_at?.slice(0,10) }}</small></td><td>{{ item.inquiry?.reference }}<small>{{ item.inquiry?.client?.company_name }}</small></td><td>v{{ item.version }}</td><td>{{ money(item.estimated_cost_total,item.currency) }}</td><td>{{ money(item.funding_required_total,item.currency) }}</td><td><span class="commercial-status" :class="`status-${item.status}`">{{ item.status.replaceAll('_',' ') }}</span></td><td class="commercial-actions"><button @click="openEstimate(item)">View</button><button v-if="['draft','revision_requested'].includes(item.status) && can('cost-estimates.update')" @click="openEstimate(item,true)">Edit</button><button v-if="['draft','revision_requested'].includes(item.status) && can('cost-estimates.submit')" @click="submitEstimate(item)">Submit</button><button v-if="item.status === 'submitted' && can('cost-estimates.review')" @click="reviewEstimate(item)">Review</button><button v-if="['approved','rejected'].includes(item.status) && can('cost-estimates.create')" @click="selected = item; post(`/api/commercial/cost-estimates/${item.id}/revise`,{reason:'Commercial revision requested'},'Estimate revision created.')">New revision</button></td></tr><tr v-if="!busy && !estimates.length && !error"><td colspan="7" class="ifc-empty">No cost estimates match these filters.</td></tr></tbody></table>
        <table v-else><thead><tr><th>QUOTATION</th><th>CLIENT / INQUIRY</th><th>VERSION</th><th>OFFER VALUE</th><th>STATUS</th><th>VALID THROUGH</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="item in quotes" :key="item.id"><td><b>{{ item.reference }}</b><small>{{ item.owner?.name }}</small></td><td>{{ item.client?.company_name }}<small>{{ item.inquiry?.reference }}</small></td><td>v{{ item.version }}</td><td>{{ money(item.total,item.currency) }}</td><td><span class="commercial-status" :class="`status-${item.status}`">{{ item.status.replaceAll('_',' ') }}</span></td><td>{{ item.valid_until }}</td><td class="commercial-actions"><button @click="openQuote(item)">View</button><button v-if="['draft','revision_requested'].includes(item.status) && can('quotations.update')" @click="openQuote(item,true)">Edit</button><button v-if="['draft','revision_requested'].includes(item.status) && can('quotations.submit')" @click="submitQuote(item)">Submit</button><button v-if="item.status === 'submitted' && can('quotations.review')" @click="reviewQuote(item)">Review</button><button v-if="item.status === 'submitted' && item.can_finalize && can('quotations.approve')" @click="selected = item; post(`/api/commercial/quotations/${item.id}/approve`,{},'Quotation approved internally.')">Approve</button><button v-if="item.status === 'approved' && can('quotations.issue')" @click="selected = item; post(`/api/commercial/quotations/${item.id}/issue`,{},'Quotation issued to client.')">Issue</button><button v-if="item.status === 'issued' && can('quotations.client-response.record')" @click="clientResponse(item)">Client response</button><button v-if="['approved','issued','client_accepted','client_rejected','rejected','expired','superseded'].includes(item.status) && can('quotations.revise')" @click="newVersion(item)">New version</button><a v-if="can('quotations.export') && ['approved','issued','client_accepted','client_rejected','superseded'].includes(item.status)" :href="`/sales/quotations/${item.id}/print`" target="_blank" rel="noopener">Print</a><button v-if="can('quotations.history.view')" @click="compare(item)">Compare</button></td></tr><tr v-if="!busy && !quotes.length && !error"><td colspan="7" class="ifc-empty">No quotations match these filters.</td></tr></tbody></table></div>
      <footer v-if="lastPage > 1" class="commercial-pagination"><span>Page {{ pageNumber }} of {{ lastPage }}</span><div><button :disabled="pageNumber <= 1 || busy" @click="pageNumber--; load()">Previous</button><button :disabled="pageNumber >= lastPage || busy" @click="pageNumber++; load()">Next</button></div></footer>
    </section>
    <div v-if="dialog && !dialog.endsWith('-view')" class="ifc-overlay" @click.self="dialog = ''"><form class="ifc-modal commercial-modal" role="dialog" aria-modal="true" @submit.prevent="dialog === 'estimate' ? saveEstimate() : dialog === 'quote' ? saveQuote() : dialog.includes('review') ? saveReview() : dialog === 'client-response' ? post(`/api/commercial/quotations/${selected.id}/client-response`,responseForm,'Client response recorded.') : dialog === 'quote-revision' ? post(`/api/commercial/quotations/${selected.id}/revise`,revisionForm,'New version created.') : null">
      <header class="ifc-panel-head"><div><h2>{{ dialog === 'estimate' ? `${selected ? 'Edit' : 'New'} cost estimate` : dialog === 'quote' ? `${selected ? 'Edit' : 'New'} quotation` : dialog === 'estimate-review' ? 'Review cost estimate' : dialog === 'quote-review' ? 'Review quotation' : dialog === 'client-response' ? 'Record client response' : 'Create quotation revision' }}</h2><p v-if="selected">{{ selected.reference }}  {{ selected.status?.replaceAll('_',' ') }}</p></div><button type="button" class="ifc-close" aria-label="Close dialog" @click="dialog = ''">&times;</button></header>
      <template v-if="dialog === 'estimate'"><label>Client inquiry<select v-model="estimateForm.inquiry_id" required :disabled="Boolean(selected?.id)"><option value="" disabled>Select an inquiry</option><option v-for="item in inquiries" :key="item.id" :value="item.id">{{ item.reference }}  {{ item.client?.company_name }}  {{ item.origin }} to {{ item.destination }}</option></select></label><label>Forecast month<select v-model="estimateForm.forecast_id" :disabled="Boolean(selected?.id)"><option value="">No forecast selected</option><option v-for="item in matchingForecasts" :key="item.id" :value="item.id">{{ item.forecast_month?.slice(0,7) }}  {{ item.expected_shipment_count }} expected</option></select></label><label>Estimate currency<input v-model="estimateForm.currency" maxlength="3" pattern="[A-Za-z]{3}" required></label><label>Assumptions<textarea v-model="estimateForm.assumptions" maxlength="4000"></textarea></label><div class="commercial-lines-head"><h3>Expense lines</h3><button type="button" @click="addLine(estimateForm.lines,makeEstimateLine)">Add line</button></div><article v-for="(line,index) in estimateForm.lines" :key="index" class="commercial-line-editor"><label>Category<select v-model="line.category"><option v-for="category in ['shipping_line','ocean_air_freight','port_terminal','trucking_transport','forwarding','customs_processing','duties_taxes','documentation','warehousing','handling_labor','insurance','cash_advance_cost','miscellaneous','contingency','other']" :key="category" :value="category">{{ category.replaceAll('_',' ') }}</option></select></label><label>Description<input v-model="line.description" maxlength="180" required></label><label>Supplier<input v-model="line.supplier" maxlength="180"></label><div class="commercial-fields"><label>Quantity<input v-model="line.quantity" type="text" inputmode="decimal" required></label><label>Unit<input v-model="line.unit" maxlength="32" required></label><label>Unit cost<input v-model="line.unit_cost" type="text" inputmode="decimal" required></label><label>Currency<input v-model="line.currency" maxlength="3" pattern="[A-Za-z]{3}" required></label></div><template v-if="line.currency.toUpperCase() !== estimateForm.currency.toUpperCase()"><label>Exchange rate to estimate currency<input v-model="line.exchange_rate_to_estimate" type="text" inputmode="decimal" required></label><div class="commercial-fields"><label>Exchange rate source<input v-model="line.exchange_rate_source" maxlength="120" placeholder="Provider or rate sheet"></label><label>Exchange rate date<input v-model="line.exchange_rate_date" type="date"></label></div></template><div class="commercial-fields"><label>Tax handling<select v-model="line.tax_treatment"><option value="none">No tax</option><option value="exclusive">Added</option><option value="inclusive">Included</option></select></label><label>Tax rate %<input v-model="line.tax_rate" type="text" inputmode="decimal"></label><label>Cost type<select v-model="line.cost_type"><option value="direct">Direct</option><option value="indirect">Indirect</option></select></label><label>Cost payer<select v-model="line.cost_payer"><option value="company">Company</option><option value="client">Client</option></select></label></div><div class="commercial-fields"><label>Recoverability<select v-model="line.recoverability"><option value="recoverable">Recoverable</option><option value="nonrecoverable">Nonrecoverable</option></select></label><label class="commercial-check"><input v-model="line.funding_required" type="checkbox"> Include in funding requirement</label></div><label>Notes<input v-model="line.notes" maxlength="2000"></label><button v-if="estimateForm.lines.length > 1" type="button" class="commercial-remove" @click="removeLine(estimateForm.lines,index)">Remove line</button></article></template>
      <template v-else-if="dialog === 'quote'"><label>Approved cost estimate<select v-model="quoteForm.cost_estimate_id" required :disabled="Boolean(selected?.id)" @change="chooseEstimate"><option value="" disabled>Select an approved estimate</option><option v-for="item in approvedEstimates" :key="item.id" :value="item.id">{{ item.reference }}  {{ item.inquiry?.client?.company_name }}  {{ money(item.estimated_cost_total,item.currency) }}</option></select></label><div class="commercial-fields"><label>Service scope<input v-model="quoteForm.service_scope" maxlength="240" required></label><label>Client contact<input v-model="quoteForm.client_contact" maxlength="120"></label><label>Origin<input v-model="quoteForm.origin" maxlength="180" required></label><label>Destination<input v-model="quoteForm.destination" maxlength="180" required></label><label>Cargo description<input v-model="quoteForm.cargo_description" maxlength="220" required></label><label>Planned shipment date<input v-model="quoteForm.planned_window" type="date"></label><label>Valid through<input v-model="quoteForm.valid_until" type="date" required></label><label>Payment terms<input v-model="quoteForm.payment_terms" maxlength="180"></label></div><div class="commercial-lines-head"><h3>Selling lines</h3><button type="button" @click="addLine(quoteForm.lines,makeQuoteLine)">Add line</button></div><article v-for="(line,index) in quoteForm.lines" :key="index" class="commercial-line-editor"><div class="commercial-fields"><label>Description<input v-model="line.description" maxlength="180" required></label><label>Quantity<input v-model="line.quantity" type="text" inputmode="decimal" required></label><label>Unit<input v-model="line.unit" maxlength="32" required></label><label>Unit price<input v-model="line.unit_price" type="text" inputmode="decimal" required></label><label>Discount<select v-model="line.discount_type"><option value="none">None</option><option value="percent">Percent</option><option value="amount">Amount</option></select></label><label>Discount value<input v-model="line.discount_value" type="text" inputmode="decimal"></label><label>Tax handling<select v-model="line.tax_treatment"><option value="none">No tax</option><option value="exclusive">Added</option><option value="inclusive">Included</option></select></label><label>Tax rate %<input v-model="line.tax_rate" type="text" inputmode="decimal"></label></div><button v-if="quoteForm.lines.length > 1" type="button" class="commercial-remove" @click="removeLine(quoteForm.lines,index)">Remove line</button></article><label>Terms<textarea v-model="quoteForm.terms" maxlength="4000"></textarea></label><label>Exclusions<textarea v-model="quoteForm.exclusions" maxlength="4000"></textarea></label><label>Assumptions<textarea v-model="quoteForm.assumptions" maxlength="4000"></textarea></label><label>Client remarks<textarea v-model="quoteForm.customer_remarks" maxlength="4000"></textarea></label><label>Internal notes (not shown on client document)<textarea v-model="quoteForm.internal_notes" maxlength="4000"></textarea></label><section class="commercial-preview"><label>Target gross margin %<input v-model="targetMargin" type="text" inputmode="decimal" placeholder="Optional configured target"></label><button type="button" class="sales-secondary" @click="marginPreview">Calculate margin preview</button><p v-if="preview">Gross profit {{ money(preview.gross_profit,approvedEstimates.find(e => String(e.id) === String(quoteForm.cost_estimate_id))?.currency) }}  margin {{ preview.gross_margin_percent ?? 'N/A' }}%  markup {{ preview.markup_percent ?? 'N/A' }}% <b v-if="preview.warning">{{ preview.warning.replaceAll('_',' ') }}</b></p><small v-if="preview?.required_selling_price_at_target_margin">Required selling price at target: {{ money(preview.required_selling_price_at_target_margin,approvedEstimates.find(e => String(e.id) === String(quoteForm.cost_estimate_id))?.currency) }}</small></section></template>
      <template v-else-if="dialog === 'estimate-review' || dialog === 'quote-review'"><label>Decision<select v-model="reviewForm.decision"><option value="approved">Approve review step</option><option value="revision_requested">Request revision</option><option value="rejected">Reject</option></select></label><label v-if="dialog === 'quote-review'">Review stage<select v-model="reviewForm.stage"><option v-if="roles.includes('Accounting') || roles.includes('Administrator')" value="accounting">Accounting</option><option v-if="roles.includes('Finance') || roles.includes('Administrator')" value="finance">Finance</option><option v-if="roles.includes('Executive') || roles.includes('Administrator')" value="executive">Executive</option></select></label><label>Remarks<textarea v-model="reviewForm.remarks" required minlength="3" maxlength="2000"></textarea></label></template>
      <template v-else-if="dialog === 'client-response'"><label>Client response<select v-model="responseForm.response"><option value="accepted">Accepted</option><option value="rejected">Rejected</option></select></label><label>Client representative<input v-model="responseForm.client_representative" maxlength="120" required></label><label>Response date<input v-model="responseForm.responded_at" type="datetime-local" required></label><label>Acceptance evidence reference<input v-model="responseForm.evidence_reference" maxlength="500" :required="responseForm.response === 'accepted'" placeholder="Secure document reference"></label><label>Remarks<textarea v-model="responseForm.remarks" maxlength="2000"></textarea></label></template>
      <template v-else-if="dialog === 'quote-revision'"><label>Approved cost estimate<select v-model="revisionForm.cost_estimate_id" required><option value="" disabled>Select estimate</option><option v-for="item in approvedEstimates.filter(e => e.inquiry_id === selected.inquiry_id)" :key="item.id" :value="item.id">{{ item.reference }} v{{ item.version }}</option></select></label><label>Reason for revision<textarea v-model="revisionForm.reason" required minlength="3" maxlength="2000"></textarea></label></template>
      <footer class="sales-dialog-actions"><button type="button" class="sales-secondary" @click="dialog = ''; preview = null">Cancel</button><button class="ifc-primary" :disabled="saving">{{ saving ? 'Saving' : dialog.includes('review') ? 'Record review' : dialog === 'client-response' ? 'Record response' : dialog === 'quote-revision' ? 'Create version' : 'Save draft' }}</button></footer>
    </form></div>
    <div v-if="dialog === 'estimate-view' && detail" class="ifc-overlay" @click.self="dialog = ''"><section class="ifc-modal commercial-modal"><header class="ifc-panel-head"><div><h2>{{ detail.reference }}  Cost breakdown</h2><p>{{ detail.inquiry?.reference }}  {{ detail.inquiry?.client?.company_name }}  v{{ detail.version }}</p></div><button class="ifc-close" aria-label="Close" @click="dialog = ''">&times;</button></header><div class="commercial-summary"><article v-for="(label,key) in {direct_cost_total:'Direct costs',indirect_cost_total:'Indirect allocation',contingency_total:'Contingency',estimated_cost_total:'Estimated total',funding_required_total:'Funding required',recoverable_total:'Recoverable',nonrecoverable_total:'Nonrecoverable'}" :key="key"><small>{{ label }}</small><b>{{ money(detail[key],detail.currency) }}</b></article></div><div class="ifc-table-wrap"><table><thead><tr><th>CATEGORY</th><th>DESCRIPTION</th><th>QTY</th><th>UNIT COST</th><th>ESTIMATE VALUE</th><th>FUNDING</th></tr></thead><tbody><tr v-for="line in detail.lines" :key="line.id"><td>{{ line.category.replaceAll('_',' ') }}</td><td>{{ line.description }}<small>{{ line.supplier }}</small></td><td>{{ line.quantity }} {{ line.unit }}</td><td>{{ money(line.unit_cost,line.currency) }}</td><td>{{ money(line.estimate_currency_total,detail.currency) }}</td><td>{{ line.funding_required ? 'Required' : 'Not flagged' }}</td></tr></tbody></table></div><p class="commercial-note">Funding is planned exposure, not a cash payment or journal entry.</p><footer class="sales-dialog-actions"><button class="sales-secondary" @click="dialog = ''">Close</button><button v-if="detail.status === 'draft' && can('cost-estimates.update')" class="ifc-primary" @click="openEstimate(detail,true)">Edit draft</button></footer></section></div>
    <div v-if="dialog === 'quote-view' && detail" class="ifc-overlay" @click.self="dialog = ''"><section class="ifc-modal commercial-modal"><header class="ifc-panel-head"><div><h2>{{ detail.reference }}  {{ detail.client?.company_name }}</h2><p>Version {{ detail.version }}  {{ detail.status.replaceAll('_',' ') }}</p></div><button class="ifc-close" aria-label="Close" @click="dialog = ''">&times;</button></header><div class="commercial-quote-summary"><b>{{ detail.service_scope }}</b><span>{{ detail.origin }}  {{ detail.destination }}</span><span>Valid through {{ detail.valid_until }}</span><strong>{{ money(detail.total,detail.currency) }}</strong></div><div class="ifc-table-wrap"><table><thead><tr><th>SELLING LINE</th><th>QTY</th><th>RATE</th><th>DISCOUNT</th><th>TAX</th><th>TOTAL</th></tr></thead><tbody><tr v-for="line in detail.lines" :key="line.id"><td>{{ line.description }}</td><td>{{ line.quantity }} {{ line.unit }}</td><td>{{ money(line.unit_price,detail.currency) }}</td><td>{{ money(line.discount_amount,detail.currency) }}</td><td>{{ money(line.tax_amount,detail.currency) }}</td><td>{{ money(line.line_total,detail.currency) }}</td></tr></tbody></table></div><div v-if="detail.margin_preview" class="commercial-margin"><b>Projected gross profit {{ money(detail.margin_preview.gross_profit,detail.currency) }}  margin {{ detail.margin_preview.gross_margin_percent ?? 'N/A' }}%</b><span v-if="detail.margin_preview.warning">{{ detail.margin_preview.warning.replaceAll('_',' ') }}</span></div><p v-if="detail.terms"><b>Terms:</b> {{ detail.terms }}</p><p v-if="detail.exclusions"><b>Exclusions:</b> {{ detail.exclusions }}</p><section v-if="detail.approvals?.length" class="commercial-history"><h3>Reviews</h3><article v-for="item in detail.approvals" :key="item.id"><b>{{ item.stage }}  {{ item.action }}</b><small>{{ item.actor?.name || 'System' }}  {{ item.acted_at }}</small><p>{{ item.remarks }}</p></article></section><section v-if="detail.responses?.length" class="commercial-history"><h3>Client responses</h3><article v-for="item in detail.responses" :key="item.id"><b>{{ item.response }}  {{ item.client_representative }}</b><small>Version {{ item.quotation_version }}  {{ item.responded_at }}</small><p>{{ item.evidence_reference }} {{ item.remarks }}</p></article></section><footer class="sales-dialog-actions"><a v-if="can('quotations.export') && ['approved','issued','client_accepted','client_rejected','superseded'].includes(detail.status)" class="sales-secondary" :href="`/sales/quotations/${detail.id}/print`" target="_blank" rel="noopener">Print client quotation</a><button v-if="detail.status === 'draft' && can('quotations.update')" class="sales-secondary" @click="openQuote(detail,true)">Edit draft</button><button class="sales-secondary" @click="dialog = ''">Close</button></footer></section></div>
    <section v-if="comparison" class="commercial-comparison ifc-panel"><button class="ifc-close" aria-label="Close comparison" @click="comparison = null">&times;</button><h2>Commercial version comparison</h2><div><article><b>{{ comparison.previous?.reference || 'First version' }} <small v-if="comparison.previous">v{{ comparison.previous.version }}  {{ comparison.previous.status }}</small></b><strong>{{ money(comparison.previous?.total || '0.00',comparison.previous?.currency || comparison.current.currency) }}</strong></article><span>Change {{ money(comparison.difference || '0.00',comparison.current.currency) }}</span><article><b>{{ comparison.current.reference }} <small>v{{ comparison.current.version }}  {{ comparison.current.status }}</small></b><strong>{{ money(comparison.current.total,comparison.current.currency) }}</strong><small v-if="comparison.current.margin">Gross margin {{ comparison.previous?.margin?.gross_margin_percent ?? 'N/A' }}% to {{ comparison.current.margin.gross_margin_percent ?? 'N/A' }}%</small></article></div><p v-if="comparison.changed_terms?.length">Changed terms: {{ comparison.changed_terms.join(', ') }}</p></section>
  </section>
</template>
